from dataclasses import dataclass, field
from abc import ABC
from typing import Optional, Tuple, Union
import math

from .constants import *
from .soil_enum import *

UNIT_WEIGHT_WATER = 10  # kN/m³

COARSE_SOILS = (SoilType.GRAVEL, SoilType.SAND)
FINE_SOILS = (SoilType.SILT, SoilType.CLAY)

# --- Lookup Dictionaries ---

def normalise(user_input: str) -> str:
    return user_input.strip().lower()

def enum_lookup(user_input: str, lookup: dict, err_msg: str):
    key = normalise(user_input)
    try:
        return lookup[key]
    except KeyError:
        raise ValueError(err_msg.format(user_input=user_input))

SOIL_CATEGORY_LOOKUP = {sc.value.lower(): sc for sc in SoilCategory}
SOIL_TYPE_LOOKUP = {st.label.lower(): st for st in SoilType}
SOIL_CONSISTENCY_LOOKUP = {sc.label.lower(): sc for sc in Consistency}

def get_soil_category(user_input: str) -> SoilCategory:
    return enum_lookup(user_input, SOIL_CATEGORY_LOOKUP, "Unknown soil category: {user_input}")

def get_soil_type(user_input: str) -> SoilType:
    return enum_lookup(user_input, SOIL_TYPE_LOOKUP, "Unknown soil type: {user_input}")

def get_soil_consistency(user_input: str) -> Consistency:
    return enum_lookup(user_input, SOIL_CONSISTENCY_LOOKUP, "Unknown soil consistency: {user_input}")

def classify_soil(soil_type: SoilType, consistency: Consistency) -> SoilDesignClass:
    """Classifies soil as Class 1, 2, or 3 based on type and consistency."""
    if soil_type.category == SoilCategory.COARSE:
        if consistency == Consistency.VERY_LOOSE:
            return SoilDesignClass.CLASS_3
        elif consistency == Consistency.LOOSE:
            return SoilDesignClass.CLASS_2
        elif consistency in (Consistency.MEDIUM_DENSE, Consistency.DENSE, Consistency.VERY_DENSE, Consistency.CEMENTED):
            return SoilDesignClass.CLASS_1
        else:
            raise ValueError(f"Unrecognized coarse consistency: {consistency.label}")
    elif soil_type.category == SoilCategory.FINE:
        if consistency == Consistency.VERY_SOFT:
            return SoilDesignClass.CLASS_3
        elif consistency in (Consistency.SOFT, Consistency.NONE):
            return SoilDesignClass.CLASS_2
        elif consistency in (Consistency.FIRM, Consistency.STIFF, Consistency.VERY_STIFF):
            return SoilDesignClass.CLASS_1
        else:
            raise ValueError(f"Unrecognized fine consistency: {consistency.label}")
    raise ValueError(f"Unknown soil category: {soil_type.category}")

def mid_range(numbers: Union[float, Tuple[float, ...]]) -> float:
    if isinstance(numbers, tuple):
        return (max(numbers) + min(numbers)) / 2
    return numbers

def interpolate_bearing_coefficients(value: float, coefficients_dict: dict = BEARING_CAPACITY_COEFFICIENTS) -> BearingCapacityCoefficients:
    # Sort the keys
    keys = sorted(coefficients_dict.keys())
    
    # If value is outside the range, return closest
    if value <= keys[0]:
        return coefficients_dict[keys[0]]
    if value >= keys[-1]:
        return coefficients_dict[keys[-1]]
    
    # Find the two nearest keys
    for i in range(len(keys) - 1):
        k1, k2 = keys[i], keys[i + 1]
        if k1 <= value <= k2:
            c1, c2 = coefficients_dict[k1], coefficients_dict[k2]
            # Linear interpolation
            def lerp(a, b):
                return a + (b - a) * ((value - k1) / (k2 - k1))
            n_c = lerp(c1.n_c, c2.n_c)
            n_y = lerp(c1.n_y, c2.n_y)
            n_q = lerp(c1.n_q, c2.n_q)
            return BearingCapacityCoefficients(n_c, n_y, n_q)
    # Should not reach here
    raise ValueError("Value not in range")

# --- Abstract Class Definition ---

class Soil(ABC):
    soil_type: SoilType
    consistency: Consistency
    ground_water_level: float
    water_condition: WaterCondition
    soil_category: SoilCategory

    @property
    def unit_weight(self) -> Optional[float]:
        try:
            return SOIL_UNIT_WEIGHT[self.soil_type][self.consistency][self.water_condition]
        except (KeyError, ValueError):
            return None

    @property
    def design_class(self) -> SoilDesignClass:
        return classify_soil(self.soil_type, self.consistency)
    
    @property
    def soil_passive_resistance_factor(self) -> Optional[Tuple[float, ...]]:
        try:
            return SOIL_PROPERTIES[self.soil_category][self.consistency]["soil_passive_resistance_factor"]
        except (KeyError, ValueError):
            return None
        
    @property
    def soil_sliding_resistance_factor(self) -> Optional[Tuple[float, ...]]:
        try:
            return SOIL_PROPERTIES[self.soil_category][self.consistency]["soil_sliding_resistance_factor"]
        except (KeyError, ValueError):
            return None

# --- Main Coarse Soil Data Class ---

@dataclass(slots=True)
class CoarseSoil(Soil):
    soil_type: SoilType
    consistency: Consistency
    water_condition: WaterCondition
    ground_water_level: float
    user_friction_angle: Optional[float] = field(default=None)
    soil_category: SoilCategory = SoilCategory.COARSE

    def __post_init__(self):
        if self.consistency.category != self.soil_type.category:
            raise ValueError(
                f"Consistency '{self.consistency.label}' is not valid for soil type '{self.soil_type.label}' ({self.soil_type.category.name.lower()})"
            )
        
    @property
    def friction_angle(self) -> Union[Tuple[float, ...], float]:
        if self.user_friction_angle is not None:
            return self.user_friction_angle
        return SOIL_PROPERTIES[self.soil_category][self.consistency]["friction_angle"]

    @property
    def coefficient_passive_earth_pressure(
        self,
    ) -> float:
        """Passive earth pressure coefficient."""
        if isinstance(self.friction_angle, tuple):
            friction_angle = mid_range(self.friction_angle)
            return math.tan(math.radians(45 + (friction_angle / 2))) ** 2
        else:
            friction_angle = self.friction_angle
            return math.tan(math.radians(45 + (friction_angle / 2))) ** 2
        
    @property
    def coefficient_active_earth_pressure(
        self,
    ) -> float:
        """Active earth pressure coefficient."""
        if isinstance(self.friction_angle, tuple):
            friction_angle = mid_range(self.friction_angle)
            return math.tan(math.radians(45 - (friction_angle / 2))) ** 2
        else:
            friction_angle = self.friction_angle
            return math.tan(math.radians(45 - (friction_angle / 2))) ** 2
        
    @property
    def bearing_capacity_coefficients(self) -> BearingCapacityCoefficients:
        return interpolate_bearing_coefficients(mid_range(self.friction_angle))
    
# --- Main Fine Soil Data Class ---
    
@dataclass(slots=True)
class FineSoil(Soil):
    soil_type: SoilType
    consistency: Consistency
    water_condition: WaterCondition
    ground_water_level: float
    user_undrained_shear_strength: Optional[float] = field(default=None)
    soil_category: SoilCategory = SoilCategory.FINE

    def __post_init__(self):
        if self.consistency.category != self.soil_type.category:
            raise ValueError(
                f"Consistency '{self.consistency.label}' is not valid for soil type '{self.soil_type.label}' ({self.soil_type.category.name.lower()})"
            )
    
    @property
    def undrained_shear_strength(self) -> Union[Tuple[float, ...], float, None]:
        if self.user_undrained_shear_strength is not None:
            return self.user_undrained_shear_strength
        try:
            return SOIL_PROPERTIES[self.soil_category][self.consistency]["undrained_shear_strength"]
        except KeyError:
            return None
            
    @property
    def unit_weight(self) -> Optional[float]:
        try:
            return SOIL_UNIT_WEIGHT[self.soil_type][self.consistency][self.water_condition]
        except (KeyError, ValueError):
            return None
    
# --- Factory function to safely create soil class dependant on soil type and consistency ---

def create_soil(
    soil_type: SoilType, 
    consistency: Consistency, 
    water_condition: WaterCondition, 
    ground_water_level: float, 
    user_friction_angle: Optional[float] = None,
    user_undrained_shear_strength: Optional[float] = None
) -> Soil:
    """
    Factory function to create a Soil instance with validation.
    """
    if soil_type in COARSE_SOILS:
        return CoarseSoil(soil_type, consistency, water_condition, ground_water_level, user_friction_angle)
    elif soil_type in FINE_SOILS:
        return FineSoil(soil_type, consistency, water_condition, ground_water_level, user_undrained_shear_strength)
    else:
        raise ValueError(f"Unsupported soil type: {soil_type}")

